const C1: Option<u8> = 200u8.checked_add(100);
const C2: i32 = (-7i32).div_euclid(2);
const C3: i32 = (-7i32).rem_euclid(2);
const C4: u32 = 1000u32.ilog10();
const C5: u64 = 99u64.isqrt();
const C6: u16 = 300u16.next_power_of_two();
