const C8: i16 = i16::MAX.saturating_add(5);
const C9: u32 = 0x12345678u32.swap_bytes();
const C10: Option<i64> = i64::MIN.checked_div(-1);
const C11: u8 = 7u8.wrapping_pow(9);
